// Single source of truth for the Work OS team-setup documentation.
// Rendered by build.js to the self-contained HTML documentation site.
// Inline markup: **bold**, *italic*, `code`, [text](url), {gh:GitHub wording|az:Azure wording}.
const h2 = (text, id) => ({ t: "h2", text, id });
const h3 = (text, id) => ({ t: "h3", text, id });
const p = (text) => ({ t: "p", text });
const lead = (text) => ({ t: "lead", text });
const steps = (items) => ({ t: "steps", items: items.map((i) => (typeof i === "string" ? { text: i, sub: [] } : i)) });
const step = (text, ...sub) => ({ text, sub });
const bullets = (items) => ({ t: "bullets", items });
const checklist = (items) => ({ t: "checklist", items });
const code = (lines, label) => ({ t: "code", lines: Array.isArray(lines) ? lines : [lines], label });
const say = (text) => ({ t: "say", text });                     // a prompt to type into Claude Code — copyable
const callout = (kind, text) => ({ t: "callout", kind, text }); // expected | check | note | why | dont | pass | tip
const table = (header, rows, widths) => ({ t: "table", header, rows, widths });
const terms = (items) => ({ t: "terms", items });
const platform = (name, ...blocks) => ({ t: "platform", name, blocks }); // "github" | "azure"
const method = (name, ...blocks) => ({ t: "method", name, blocks });     // "app" (Settings › Connectors — default) | "chat" (Claude does the whole setup in the conversation)
const details = (summary, ...blocks) => ({ t: "details", summary, blocks });
const image = (file, alt, caption) => ({ t: "image", file, alt, caption });   // file in the build folder; the HTML embeds it
const seq = (items) => ({ t: "seq", items });                    // the big-picture sequence: [{who, what, time, link}]
const cards = (items) => ({ t: "cards", items });                // [{title, text, link}]
const legend = (items) => ({ t: "legend", items });              // file-kind legend: [{kind, name, what, treat}] — kind: steering|registry|living|raw|deliverable|template
const catalog = (rows) => ({ t: "catalog", rows });              // context-map rows: [{name, kind, what, use}] — kind rendered as a colored chip
const flowmap = (stages) => ({ t: "flowmap", stages });          // lifecycle map: [{name, desc, skills:[{s, main?}]}]
const loop = (nodes, links) => ({ t: "loop", nodes, links });    // sync loop: nodes [{title, sub}], links [{label}] between them

const ADO_FILTER = "/product-development/feature-index.yaml;/product-development/toolchain.yaml;/product-development/product/strategy/business-context/*;/product-development/product/handbook/templates/*;/product-development/engineering/*;/CLAUDE.md;/governance/*;/os-installation/*;/Documentation/*;/.claude/*;/.github/*";

